+#[test]
+fn terminal_app_review_completion_prompt_closes_and_reopens_patch_chat() {
+    let root = git_repo("terminal-app-review-completion");
+    fs::write(root.join("README.md"), "before\n").unwrap();
+    Command::new("git")
+        .current_dir(&root)
+        .args(["add", "README.md"])
+        .status()
+        .unwrap();
+    Command::new("git")
+        .current_dir(&root)
+        .args(["commit", "-m", "ADD initial readme fixture"])
+        .status()
+        .unwrap();
+    let backend = FakeBackend::new([
+        "implemented patch\n@work-leaf patch update readme\n--- a/README.md\n+++ b/README.md\n@@ -1 +1 @@\n-before\n+after\n@work-leaf end\n@work-leaf done",
+        "summary: README changes from before to after",
+        "NO_FINDINGS",
+        "follow-up reply",
+    ]);
+    let chat = CommandChat::new(root, backend).with_max_review_rounds(4);
+    let mut app = TerminalApp::new(chat, 100, 24);
+
+    app.handle_bytes(b":new patch update readme\n");
+
+    assert!(app.wait_for_idle(Duration::from_secs(2)));
+    assert_eq!(
+        app.ui().selected_agent().map(AgentId::as_str),
+        Some("user-1")
+    );
+    let prompted_frame = app.render_frame();
+    assert!(prompted_frame.contains("work-leaf: Is this feature done? yes/no"));
+    assert!(
+        app.ui()
+            .render_left_pane()
+            .contains("\u{1b}[7m>patch user-1  working: patch  READY\u{1b}[0m")
+    );
+
+    app.handle_bytes(b"yes\n");
+    assert!(app.wait_for_idle(Duration::from_secs(1)));
+    let closed_frame = app.render_frame();
+    assert!(closed_frame.contains("work-leaf: feature closed"));
+    assert!(
+        !app.ui().render_left_pane().contains("patch user-1"),
+        "{}",
+        app.ui().render_left_pane()
+    );
+
+    app.handle_bytes(b"add one more adjustment\n");
+    assert!(app.wait_for_idle(Duration::from_secs(1)));
+    let reopened_frame = app.render_frame();
+    assert!(reopened_frame.contains("work-leaf: feature reopened"));
+    assert!(reopened_frame.contains("user: add one more adjustment"));
+    assert!(reopened_frame.contains("follow-up reply"));
+    assert!(app.ui().render_left_pane().contains("patch user-1"));
+
+    let backend = app.into_chat().into_backend();
+    let sends = backend.sends();
+    assert!(
+        !sends
+            .iter()
+            .any(|(target, prompt)| target.as_str() == "user-1" && prompt == "yes"),
+        "{sends:?}"
+    );
+    assert!(sends.iter().any(|(target, prompt)| {
+        target.as_str() == "user-1" && prompt == "add one more adjustment"
+    }));
+}
+
+#[test]
+fn terminal_app_shows_second_review_completion_prompt_for_same_patch_chat() {
+    let root = git_repo("terminal-app-review-completion-repeat");
+    fs::write(root.join("README.md"), "before\n").unwrap();
+    Command::new("git")
+        .current_dir(&root)
+        .args(["add", "README.md"])
+        .status()
+        .unwrap();
+    Command::new("git")
+        .current_dir(&root)
+        .args(["commit", "-m", "ADD initial readme fixture"])
+        .status()
+        .unwrap();
+    let first_patch = "implemented patch\n@work-leaf patch update readme\n--- a/README.md\n+++ b/README.md\n@@ -1 +1 @@\n-before\n+after\n@work-leaf end\n@work-leaf done";
+    let second_patch = format!(
+        "{}\n@work-leaf patch update readme again\n--- a/README.md\n+++ b/README.md\n@@ -1 +1 @@\n-after\n+after again\n@work-leaf end\n@work-leaf done",
+        (0..30)
+            .map(|index| format!("second patch progress line {index:02}"))
+            .collect::<Vec<_>>()
+            .join("\n")
+    );
+    let backend = FakeBackend::from_replies(
+        [
+            first_patch.to_string(),
+            "summary: README changes from before to after".to_string(),
+            "NO_FINDINGS".to_string(),
+            second_patch,
+            "summary: README changes from after to after again".to_string(),
+            "NO_FINDINGS".to_string(),
+        ]
+        .into_iter()
+        .collect(),
+    );
+    let chat = CommandChat::new(root, backend).with_max_review_rounds(4);
+    let mut app = TerminalApp::new(chat, 100, 24);
+
+    app.handle_bytes(b":new patch update readme\n");
+    assert!(app.wait_for_idle(Duration::from_secs(2)));
+    app.handle_bytes(b"yes\n");
+    assert!(app.wait_for_idle(Duration::from_secs(1)));
+    app.handle_bytes(b"add one more adjustment\n");
+
+    assert!(app.wait_for_idle(Duration::from_secs(2)));
+    let second_prompt_frame = app.render_frame();
+    assert!(
+        second_prompt_frame.contains("work-leaf: Is this feature done? yes/no"),
+        "{second_prompt_frame}"
+    );
+    assert!(
+        app.ui()
+            .render_left_pane()
+            .contains("\u{1b}[7m>patch user-1  working: patch  READY\u{1b}[0m")
+    );
+
+    app.handle_bytes(b"yes\n");
+    assert!(app.wait_for_idle(Duration::from_secs(1)));
+    assert!(
+        !app.ui().render_left_pane().contains("patch user-1"),
+        "{}",
+        app.ui().render_left_pane()
+    );
+
+    let backend = app.into_chat().into_backend();
+    let sends = backend.sends();
+    assert_eq!(
+        sends
+            .iter()
+            .filter(|(target, prompt)| target.as_str() == "user-1" && prompt == "yes")
+            .count(),
+        0,
+        "{sends:?}"
+    );
+}
